(()=>{
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=800,H=500,T=32,world={w:1800,h:1200};
const saveKey='abu-rimba-save-v1';
const fresh=()=>({started:false,x:390,y:300,hp:100,st:100,hunger:82,coins:12,xp:0,level:1,day:1,phase:0,quest:0,kills:0,rep:0,married:false,inventory:{'Herba':2,'Roti':1,'Kayu':0,'Batu':0,'Kulit':0,'Ramuan':0,'Pedang':0},seen:{},time:0});
let S;try{S={...fresh(),...JSON.parse(localStorage.getItem(saveKey)||'{}')};S.inventory={...fresh().inventory,...(S.inventory||{})}}catch{S=fresh()}
let keys={},last=performance.now(),toastTimer=0,attack=0,dialogueLock=false,muted=false;
const terrain=[];let seed=80413;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}for(let y=0;y<40;y++){terrain[y]=[];for(let x=0;x<60;x++)terrain[y][x]=rand()}
const places=[{x:400,y:310,name:'Pinggiran Rimba',title:'Tanah Buangan',sub:'Tak ada yang menunggumu di sini.'},{x:805,y:320,name:'Kampung Lumut',title:'Kampung Lumut',sub:'Asap dapur dan kabar buruk.'},{x:1270,y:370,name:'Hutan Terlarang',title:'Hutan Terlarang',sub:'Sesuatu bergerak di balik pepohonan.'},{x:1410,y:840,name:'Kota Bara',title:'Kota Bara',sub:'Di sini, kekuatan adalah mata uang.'},{x:820,y:900,name:'Arena Serigala',title:'Arena Serigala',sub:'Tempat Raka mengukir namanya.'}];
let npcs=[{id:'elder',x:590,y:320,name:'Tetua Sari',type:'person'},{id:'mira',x:850,y:365,name:'Mira',type:'person'},{id:'merchant',x:925,y:315,name:'Pedagang',type:'person'},{id:'raka',x:835,y:950,name:'Raka si Serigala',type:'rival'}];
let enemies=[];const enemyTypes=[{name:'Serigala',color:'#b8b39a',hp:30,damage:8,xp:18,loot:'Kulit'},{name:'Perampok',color:'#b9644b',hp:42,damage:12,xp:25,loot:'Koin'},{name:'Babi Hutan',color:'#96674a',hp:38,damage:10,xp:20,loot:'Daging'}];
function spawnEnemies(){enemies=[];for(let i=0;i<17;i++){let p=places[i%places.length];let type=enemyTypes[i%3];enemies.push({x:p.x+(rand()-.5)*270,y:p.y+(rand()-.5)*230,hp:type.hp,maxHp:type.hp,...type,alive:true,seed:rand()*8})}}spawnEnemies();
const itemIcons={Herba:'✿',Roti:'▰',Kayu:'⌁',Batu:'◆',Kulit:'◈',Ramuan:'⚗',Pedang:'⚔',Daging:'●',Koin:'◉'};
function persist(){localStorage.setItem(saveKey,JSON.stringify(S))}
function pop(msg){const el=document.querySelector('#toast-pop');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function sceneToast(msg){let el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function objective(){return ['Cari seseorang di dekat api unggun','Bawa 3 herba ke Tetua Sari','Kalahkan 3 musuh di Hutan Terlarang','Temui Raka di Arena Serigala','Kumpulkan 50 koin dan temui Mira','Kalahkan Raka di arena','Pulanglah ke Mira'][Math.min(S.quest,6)]}
function sync(){let pct=(v,max)=>Math.max(0,Math.min(100,v/max*100)) ;document.querySelector('#health-value').textContent=`${S.hp} / 100`;document.querySelector('#health-fill').style.width=pct(S.hp,100)+'%';document.querySelector('#stamina-value').textContent=`${Math.round(S.st)} / 100`;document.querySelector('#stamina-fill').style.width=pct(S.st,100)+'%';document.querySelector('#hunger-value').textContent=`${Math.round(S.hunger)} / 100`;document.querySelector('#hunger-fill').style.width=pct(S.hunger,100)+'%';document.querySelector('#coin-count').textContent=S.coins;document.querySelector('#level').textContent=String(S.level).padStart(2,'0');document.querySelector('#xp-text').textContent=S.xp;document.querySelector('#xp-fill').style.width=(S.xp%100)+'%';document.querySelector('#player-title').textContent=S.level>=6?'Penguasa Rimba':S.level>=3?'Petarung Rimba':'Anak Buangan';document.querySelector('#quest-objective').textContent=objective();document.querySelector('#quest-count').textContent=String(S.quest+1).padStart(2,'0');document.querySelector('#relationship').textContent=S.married?'♡ MENIKAH DENGAN MIRA':'♡ MASIH SENDIRI';document.querySelector('#chapter-label').textContent=S.quest>=3?'BAB II · SERIGALA DI ARENA':'BAB I · ANAK YANG DIBUANG';let g=document.querySelector('#inventory-grid');g.innerHTML='';for(let [n,v] of Object.entries(S.inventory)){if(v<=0)continue;let d=document.createElement('div');d.className='item-slot';d.title=n;d.innerHTML=`${itemIcons[n]||'◇'}<small>${v}</small>`;g.appendChild(d)}while(g.children.length<10){let d=document.createElement('div');d.className='item-slot';d.style.opacity='.28';d.textContent='·';g.appendChild(d)}document.querySelector('#intro-screen').classList.toggle('hidden',S.started);}
function addXP(n){S.xp+=n;while(S.xp>=100){S.xp-=100;S.level++;S.hp=Math.min(100,S.hp+25);pop(`NAIK LEVEL! Sekarang level ${S.level}`)}sync()}
function openDialog({eyebrow='PERCakapan',title,text,choices=[]}){dialogueLock=true;document.querySelector('#dialog-eyebrow').textContent=eyebrow.toUpperCase();document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-text').textContent=text;let o=document.querySelector('#dialog-options');o.innerHTML='';choices.forEach(c=>{let b=document.createElement('button');b.className='dialog-choice';b.textContent=c.label;b.onclick=()=>{if(c.action)c.action();closeDialog()};o.appendChild(b)});if(!choices.length){let b=document.createElement('button');b.className='dialog-choice';b.textContent='LANJUTKAN →';b.onclick=closeDialog;o.appendChild(b)}document.querySelector('#dialog-backdrop').classList.add('open')}
function closeDialog(){document.querySelector('#dialog-backdrop').classList.remove('open');dialogueLock=false;persist();sync()}
document.querySelector('#dialog-close').onclick=closeDialog;
function startGame(){S.started=true;sync();persist();openDialog({eyebrow:'MALAM ITU, SEPULUH TAHUN LALU',title:'Abu bukan nama lahirmu.',text:'Ayahmu menolak membayar upeti pada Raka. Rumah kalian dibakar, dan kau dipaksa bertarung di arena sampai pingsan. Raka mengira kau mati. Sejak malam itu, kau hidup sebagai orang buangan—lapar, sendirian, dan menyimpan satu nama.',choices:[{label:'AKU AKAN BERTAHAN. →',action:()=>{}}]})}
document.querySelector('#start-button').onclick=startGame;
function nearest(){let a=[];npcs.forEach(n=>a.push({obj:n,d:Math.hypot(n.x-S.x,n.y-S.y),kind:'npc'}));let camp={x:390,y:340,name:'Api unggun',id:'camp'};a.push({obj:camp,d:Math.hypot(camp.x-S.x,camp.y-S.y),kind:'camp'});return a.sort((a,b)=>a.d-b.d)[0]}
function interact(){let n=nearest();if(n.d>66){sceneToast('Tak ada siapa-siapa di dekatmu.');return}if(n.kind==='camp'){openDialog({eyebrow:'API UNGGUN',title:'Istirahat sejenak?',text:'Api kecil ini mengingatkanmu pada rumah yang hilang. Istirahat memulihkan tenaga, tapi hari terus berjalan.',choices:[{label:'ISTIRAHAT · pulihkan nyawa dan stamina',action:()=>{S.hp=100;S.st=100;S.day++;S.hunger=Math.max(0,S.hunger-8);pop('Istirahat selesai. Hari baru dimulai.')}},{label:'TINGGALKAN API'}]});return}
if(n.obj.id==='elder'){if(S.quest===0){S.quest=1;openDialog({eyebrow:'TETUA SARI',title:'Kau anaknya Daru.',text:'Aku mengenali matamu. Ayahmu pernah menolong kampung ini sebelum Raka membakarnya. Ambil herba di sekitar rimba—bawa tiga, dan kuberi tahu jalan menuju Kota Bara.',choices:[{label:'AKU AKAN MENCARINYA.',action:()=>{}}]})}else if(S.quest===1){if(S.inventory.Herba>=3){S.inventory.Herba-=3;S.quest=2;S.coins+=20;addXP(40);openDialog({eyebrow:'TETUA SARI · MISI SELESAI',title:'Kebaikan tak pernah gratis.',text:'Terima kasih. Hutan Terlarang penuh perampok Raka. Kalahkan tiga dari mereka—dan berhati-hatilah. Raka sedang mencari jejakmu.',choices:[{label:'AKU TAK TAKUT PADANYA.',action:()=>{}}]})}else openDialog({eyebrow:'TETUA SARI',title:'Belum cukup.',text:`Kau punya ${S.inventory.Herba} dari 3 herba. Cari bunga kecil di tanah, lalu tekan E di dekatnya.`})}else openDialog({eyebrow:'TETUA SARI',title:'Jangan biarkan dendam memakanmu.',text:'Ayahmu ingin kau hidup, bukan menjadi seperti Raka. Ingat itu saat kau punya pilihan.'});return}
if(n.obj.id==='merchant'){openDialog({eyebrow:'PEDAGANG KOTA',title:'Barang bagus, harga jujur.',text:`Koinmu: ${S.coins}. Pilih barang yang kau butuhkan.`,choices:[{label:'BELI ROTI · 5 koin',action:()=>buy('Roti',5)},{label:'BELI RAMUAN · 12 koin',action:()=>buy('Ramuan',12)},{label:'BELI PEDANG BESI · 30 koin',action:()=>buy('Pedang',30)},{label:'JUAL KULIT · +8 koin',action:()=>sell('Kulit',8)}]});return}
if(n.obj.id==='mira'){if(S.quest<4){openDialog({eyebrow:'MIRA · TABIB KAMPUNG',title:'Kau tidak harus jadi monster.',text:'Aku tahu wajah orang yang menanggung terlalu banyak. Kalau kau mau, bantu aku merawat yang terluka. Ada masa depan selain balas dendam.',choices:[{label:'AKU AKAN KEMBALI SETELAH MENGHADAPI RAKA.',action:()=>{S.rep++}},{label:'TERIMA KASIH, MIRA.'}]})}else if(S.quest===4){if(S.coins>=50){S.quest=5;S.coins-=50;S.married=true;document.querySelector('#relationship').textContent='♡ MENIKAH DENGAN MIRA';openDialog({eyebrow:'MIRA · RUMAH KECIL DI TEPI SUNGAI',title:'Kau tak perlu bertarung sendirian.',text:'Kau dan Mira membangun rumah kecil bersama. Ia tahu masih ada satu urusan yang harus kau selesaikan. “Pulanglah,” katanya. “Aku akan menunggumu.”',choices:[{label:'AKU PASTI PULANG.',action:()=>{}}]})}else openDialog({eyebrow:'MIRA',title:'Pilih hidupmu sendiri.',text:`Kota ini meminta 50 koin untuk membangun rumah aman. Kumpulkan dulu—koinmu ${S.coins}.`})}else if(S.quest>=6)openDialog({eyebrow:'MIRA',title:'Kau sudah pulang.',text:'Kau bukan lagi anak buangan. Bukan juga bayangan Raka. Kau adalah Abu—dan kau memilih hidup.',choices:[{label:'PELUK MIRA',action:()=>{S.hp=100;S.rep++}},{label:'DUDUK DI SAMPINGNYA'}]});else openDialog({eyebrow:'MIRA',title:'Aku menunggumu.',text:'Selesaikan urusanmu di arena dan pulanglah. Hanya itu yang kuminta.'});return}
if(n.obj.id==='raka'){if(S.quest<3){openDialog({eyebrow:'RAKA SI SERIGALA',title:'Lihat siapa yang kembali.',text:'Kau seharusnya mati di arena, Abu. Kembali ke sini setelah kau cukup kuat. Aku ingin semua orang menyaksikanmu jatuh lagi. (Kalahkan musuh hutan dahulu.)'});return}if(S.quest===3){S.quest=4;openDialog({eyebrow:'RAKA SI SERIGALA',title:'Akhirnya kau datang.',text:'Aku menghancurkan keluargamu karena mereka lemah. Buktikan bahwa kau berbeda. Hancurkan anak buahku di arena, lalu hadapi aku.',choices:[{label:'INI BERAKHIR HARI INI.',action:()=>{}}]});return}if(S.quest===5){let alive=enemies.filter(e=>e.alive&&Math.hypot(e.x-S.x,e.y-S.y)<350).length;if(S.inventory.Pedang===0){openDialog({eyebrow:'RAKA SI SERIGALA',title:'Tangan kosong?',text:'Pedagang di Kota Bara punya pedang. Kembalilah saat kau siap bertarung.'});return}if(S.hp<60){openDialog({eyebrow:'RAKA SI SERIGALA',title:'Kau terlihat lelah.',text:'Makan atau gunakan ramuan sebelum menantangku. Ini bukan duel yang bisa kau menangkan dengan setengah nyawa.'});return}S.quest=6;S.hp=Math.max(1,S.hp-32);addXP(100);S.coins+=70;openDialog({eyebrow:'DUEL TERAKHIR',title:'Raka jatuh.',text:'Pedangmu menghentikan pertarungan. Kau bisa membalas semua penderitaan itu—tetapi kau melihat ketakutan yang sama yang pernah kau rasakan. Kau membiarkannya hidup. Kemenanganmu adalah pilihan untuk tidak menjadi dirinya.',choices:[{label:'AKU BUKAN KAU.',action:()=>{S.quest=6;S.rep+=3}}]});return}openDialog({eyebrow:'RAKA SI SERIGALA',title:'Arena menunggu.',text:'Sudah cukup banyak darah tertumpah. Pergilah.'})}}
function buy(item,price){if(S.coins<price){pop('Koinmu tidak cukup.');return}S.coins-=price;S.inventory[item]=(S.inventory[item]||0)+1;pop(`${item} dibeli.`);sync()}
function sell(item,price){if((S.inventory[item]||0)<1){pop('Kamu tidak punya kulit untuk dijual.');return}S.inventory[item]--;S.coins+=price;pop(`Kulit dijual +${price} koin.`);sync()}
function eat(){if(S.inventory.Roti>0){S.inventory.Roti--;S.hunger=Math.min(100,S.hunger+35);S.hp=Math.min(100,S.hp+8);pop('Roti dimakan. Kenyang +35.')}else if(S.inventory.Daging>0){S.inventory.Daging--;S.hunger=Math.min(100,S.hunger+28);S.hp=Math.min(100,S.hp+5);pop('Daging dimakan.')}else if(S.inventory.Ramuan>0){S.inventory.Ramuan--;S.hp=Math.min(100,S.hp+45);pop('Ramuan memulihkan nyawa.')}else pop('Tasmu tak punya makanan. Cari herba atau beli roti.');sync();persist()}
function attackEnemy(){if(S.st<12){pop('Stamina terlalu rendah.');return}S.st-=12;attack=12;let found=enemies.find(e=>e.alive&&Math.hypot(e.x-S.x,e.y-S.y)<56);if(found){let dmg=S.inventory.Pedang?28:17;found.hp-=dmg;pop(`Serangan mengenai ${found.name}! -${dmg}`);if(found.hp<=0){found.alive=false;S.kills++;S.xp+=found.xp;let item=found.loot==='Koin'?'Koin':found.loot;if(item==='Koin')S.coins+=8;else S.inventory[item]=(S.inventory[item]||0)+1;addXP(found.xp);if(S.quest===2&&S.kills>=3){S.quest=3;addXP(60);pop('MISI SELESAI · Temui Raka di arena!')}if(S.quest===4&&S.kills>=6){S.quest=5;pop('Raka menantangmu. Temui dia di arena!')}sync()}}else sceneToast('Tak ada musuh dalam jangkauan.')}
function gather(){let x=Math.round(S.x/48),y=Math.round(S.y/48),got=false;for(let oy=-1;oy<=1;oy++)for(let ox=-1;ox<=1;ox++){let px=(x+ox)*48+24,py=(y+oy)*48+24;if(Math.hypot(px-S.x,py-S.y)<58&&!S.seen[`${x+ox},${y+oy}`]){let r=terrain[Math.min(39,Math.floor(py/30))]?.[Math.min(59,Math.floor(px/30))]||0;if(r>.76){S.seen[`${x+ox},${y+oy}`]=true;let item=r>.91?'Roti':'Herba';S.inventory[item]=(S.inventory[item]||0)+1;pop(`${item} ditemukan!`);got=true;break}}}if(!got)interact();sync()}
function interactKey(){let near=nearest();if(near.d<68)interact();else gather()}
function keydown(e){if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(dialogueLock)return;let k=e.key.toLowerCase();keys[k]=true;if(!S.started&&k==='enter'){startGame();return}if(k==='e')interactKey();if(k===' '||k==='j')attackEnemy();if(k==='q')eat();if(k==='i')document.querySelector('#inventory-toggle').click();if(k==='escape')closeDialog()}
function keyup(e){keys[e.key.toLowerCase()]=false}window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);
document.querySelector('#inventory-toggle').onclick=()=>openDialog({eyebrow:'TAS PERJALANAN',title:'Barang yang kau bawa',text:Object.entries(S.inventory).filter(x=>x[1]>0).map(([k,v])=>`${k}: ${v}`).join(' · ')||'Kosong',choices:[{label:'MAKAN ROTI / GUNAKAN RAMUAN',action:eat},{label:'TUTUP'}]});document.querySelector('#help-button').onclick=()=>openDialog({eyebrow:'PETUNJUK',title:'Bertahan hidup di Rimba',text:'Gerak dengan WASD atau tombol panah. SPACE untuk menyerang, E untuk bicara / mengambil barang, Q untuk makan, I untuk tas. Musuh menjatuhkan bahan dan XP. Beristirahat di api unggun memulihkan nyawa. Selesaikan misi untuk membuka bab berikutnya.',choices:[{label:'MENGERTI'}]});document.querySelector('#sound-button').onclick=()=>{muted=!muted;document.querySelector('#sound-button').textContent=muted?'♪':'♫';pop(muted?'Suara dimatikan':'Suara aktif')};document.querySelector('#mobile-action').onclick=()=>interactKey();document.querySelectorAll('.mobile-pad button').forEach(b=>{b.addEventListener('touchstart',e=>{e.preventDefault();keys[b.dataset.dir==='up'?'w':b.dataset.dir==='down'?'s':b.dataset.dir==='left'?'a':'d']=true});b.addEventListener('touchend',()=>{keys.w=keys.a=keys.s=keys.d=false});b.addEventListener('click',()=>{let d=b.dataset.dir;if(d==='up')S.y-=24;if(d==='down')S.y+=24;if(d==='left')S.x-=24;if(d==='right')S.x+=24;clamp()})});
function clamp(){S.x=Math.max(20,Math.min(world.w-20,S.x));S.y=Math.max(70,Math.min(world.h-20,S.y))}
function draw(){let camX=Math.max(0,Math.min(world.w-W,S.x-W/2)),camY=Math.max(0,Math.min(world.h-H,S.y-H/2));let zone= S.y<550?'forest':S.x>1120?'city':S.y>720?'arena':'village';ctx.fillStyle=zone==='city'?'#77785c':zone==='arena'?'#8a6e4a':'#456546';ctx.fillRect(0,0,W,H);
let startX=Math.floor(camX/T),startY=Math.floor(camY/T);for(let y=startY;y<Math.ceil((camY+H)/T);y++)for(let x=startX;x<Math.ceil((camX+W)/T);x++){let r=terrain[y%40]?.[x%60]||0,px=x*T-camX,py=y*T-camY;let ground=zone==='city'?['#74785a','#7f805e','#6e7556']:zone==='arena'?['#8a7049','#92764d','#806a47']:['#41633f','#466943','#3e5e3d'];ctx.fillStyle=ground[Math.floor(r*3)];ctx.fillRect(px,py,T,T);if(r>.86){ctx.fillStyle='#809050';ctx.fillRect(px+8,py+18,3,7);ctx.fillRect(px+17,py+11,3,8);ctx.fillStyle='#a5a66b';ctx.fillRect(px+9,py+17,2,2)}if(zone!=='city'&&r<.12){ctx.fillStyle='#334a35';ctx.fillRect(px+2,py+23,4,2)}}
// river and paths
ctx.fillStyle='#64896b';ctx.fillRect(0,248-camY,world.w,14);ctx.fillStyle='#9a9668';ctx.fillRect(370-camX,0,45,world.h);ctx.fillRect(780-camX,0,48,world.h);ctx.fillRect(0,840-camY,world.w,40);ctx.fillStyle='#647f55';for(let i=0;i<world.w;i+=16){ctx.fillRect(i-camX,245-camY,6,2);ctx.fillRect(i-camX,264-camY,5,2)}
// structures
places.forEach((p,i)=>{let x=p.x-camX,y=p.y-camY;if(x<-100||x>W+100||y<-100||y>H+100)return;if(i===0){drawTree(x-50,y-10,1.4);drawTree(x+95,y-15,1.2);drawFire(x,y+30)}else if(i===1||i===3){drawHouse(x-70,y-38,i===3?'#7b5541':'#97694a');drawHouse(x+65,y-10,'#78543b')}else if(i===4){ctx.fillStyle='#634b37';ctx.fillRect(x-110,y-14,220,90);ctx.strokeStyle='#c1a06b';ctx.strokeRect(x-110,y-14,220,90);ctx.fillStyle='#47382b';ctx.fillRect(x-92,y+4,184,54);ctx.fillStyle='#cfb177';ctx.fillRect(x-100,y-21,200,7)}});
// vegetation and pickup hints
for(let y=startY;y<Math.ceil((camY+H)/T);y++)for(let x=startX;x<Math.ceil((camX+W)/T);x++){let r=terrain[y%40]?.[x%60]||0;if(r>.91&&!S.seen[`${Math.floor(x*T/48)},${Math.floor(y*T/48)}`]){let px=x*T-camX+13,py=y*T-camY+10;ctx.fillStyle='#9aca68';ctx.fillRect(px,py+5,5,7);ctx.fillRect(px+4,py+2,5,5);ctx.fillStyle='#e2d88d';ctx.fillRect(px+3,py+1,3,3)}}
// npcs
npcs.forEach(n=>{let x=n.x-camX,y=n.y-camY;if(x<-30||x>W+30||y<-30||y>H+30)return;drawPerson(x,y,n.id==='raka'?'#b74f3c':n.id==='mira'?'#d18b73':n.id==='merchant'?'#c5a65f':'#a7b48b',n.id);label(n.name,x,y-25)});
// enemies
for(let e of enemies){if(!e.alive)continue;let dx=e.x-camX,dy=e.y-camY;if(dx<-30||dx>W+30||dy<-30||dy>H+30)continue;drawEnemy(dx,dy,e);if(e.hp<e.maxHp){ctx.fillStyle='#272721';ctx.fillRect(dx-10,dy-24,20,3);ctx.fillStyle='#dc6651';ctx.fillRect(dx-10,dy-24,20*e.hp/e.maxHp,3)}}
// player shadow and sprite
let px=S.x-camX,py=S.y-camY;ctx.fillStyle='#273723';ctx.fillRect(px-9,py+9,18,5);if(attack>0){ctx.strokeStyle='#e7e6a1';ctx.lineWidth=3;ctx.beginPath();ctx.arc(px+10,py,21,-1.2,1.15);ctx.stroke();}drawPlayer(px,py);
// minimap
ctx.fillStyle='#101810cc';ctx.fillRect(W-100,47,89,61);ctx.strokeStyle='#70815a';ctx.strokeRect(W-100,47,89,61);ctx.fillStyle='#9eae77';for(let p of places)ctx.fillRect(W-95+p.x/world.w*78,51+p.y/world.h*50,3,3);ctx.fillStyle='#f0da8d';ctx.fillRect(W-95+S.x/world.w*78,51+S.y/world.h*50,4,4);
// interaction prompt
let near=nearest();if(near.d<70){ctx.fillStyle='#10180fe8';ctx.fillRect(px-31,py-45,62,18);ctx.fillStyle='#d5ee9e';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('E  BICARA',px,py-33)}
}
