function drawHouse(x,y,roof){ctx.fillStyle='#4d3b2a';ctx.fillRect(x-30,y-4,60,45);ctx.fillStyle=roof;ctx.fillRect(x-37,y-15,74,16);ctx.fillRect(x-29,y-23,57,9);ctx.fillStyle='#31291f';ctx.fillRect(x-7,y+16,16,25);ctx.fillStyle='#d4bd78';ctx.fillRect(x-23,y+5,10,10);ctx.fillRect(x+17,y+5,10,10)}
