function drawEnemy(x,y,e){ctx.fillStyle='#263123';ctx.fillRect(x-10,y+9,20,5);if(e.name==='Serigala'){ctx.fillStyle=e.color;ctx.fillRect(x-12,y-7,24,16);ctx.fillRect(x-6,y-14,15,12);ctx.fillRect(x+5,y-18,5,7);ctx.fillStyle='#cf715a';ctx.fillRect(x+5,y-9,3,3);ctx.fillStyle='#6c6d5c';ctx.fillRect(x-9,y+7,5,7);ctx.fillRect(x+5,y+7,5,7)}else{ctx.fillStyle=e.color;ctx.fillRect(x-10,y-10,20,23);ctx.fillStyle='#d2a183';ctx.fillRect(x-5,y-19,10,10);ctx.fillStyle='#45362a';ctx.fillRect(x-7,y-21,14,5);ctx.fillStyle='#df7458';ctx.fillRect(x+3,y-15,2,2);ctx.fillRect(x-8,y+10,5,7);ctx.fillRect(x+3,y+10,5,7)}}
