function update(dt){if(!S.started||dialogueLock)return;S.time+=dt;S.hunger=Math.max(0,S.hunger-dt*.24);if(S.hunger===0&&Math.floor(S.time)%4===0)S.hp=Math.max(1,S.hp-.2);S.st=Math.min(100,S.st+dt*9);let dx=0,dy=0;if(keys.w||keys.arrowup)dy--;if(keys.s||keys.arrowdown)dy++;if(keys.a||keys.arrowleft)dx--;if(keys.d||keys.arrowright)dx++;if(dx||dy){let l=Math.hypot(dx,dy);let pace=S.hunger<20?90:125;S.x+=dx/l*pace*dt;S.y+=dy/l*pace*dt;clamp()}for(let e of enemies){if(!e.alive)continue;if(Math.hypot(e.x-S.x,e.y-S.y)<150){let a=Math.atan2(S.y-e.y,S.x-e.x);e.x-=Math.cos(a)*22*dt;e.y-=Math.sin(a)*22*dt;if(Math.hypot(e.x-S.x,e.y-S.y)<24&&Math.random()<dt*.75){S.hp=Math.max(1,S.hp-e.damage);sceneToast(`${e.name} menyerang! -${e.damage} nyawa`);sync()}}}let loc=places.reduce((a,p)=>Math.hypot(p.x-S.x,p.y-S.y)<Math.hypot(a.x-S.x,a.y-S.y)?p:a,places[0]);document.querySelector('#location-label').textContent=loc.name.toUpperCase();document.querySelector('#scene-title').textContent=loc.title;document.querySelector('#scene-subtitle').textContent=loc.sub;document.querySelector('#clock-label').textContent=`HARI ${S.day} · ${S.time%90<30?'FAJAR':S.time%90<60?'SIANG':'SENJA'}`;if(attack>0)attack-=dt*30;if(Math.floor(S.time)%4===0)sync()}
function loop(now){let dt=Math.min(.05,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(loop)}sync();requestAnimationFrame(loop);
})();

